#if SIMULATOR

#include "adapters/FakeNetwork.h"

#include <cstring>

#include "adapters/FakeState.h"  // generated by scripts/embed_fixture.py (gitignored)

namespace feedme2::adapters {

namespace {

constexpr int64_t kPairTtlMs = 10 * 60 * 1000;
// Mirrors backend/src/repos/feedings.ts clampFedAt: more than 5 min ahead of the server, or before
// 2020-01-01 (an RTC that never came up reports 1970), is replaced by now and reported in `clamped`.
constexpr int64_t kFedAtMaxFutureMs = 5 * 60 * 1000;
constexpr int64_t kFedAtUnsetBeforeMs = 1577836800000;

std::string serialize(const JsonDocument& doc) {
    std::string out;
    serializeJson(doc, out);
    return out;
}

ports::NetResult jsonResult(int status, const JsonDocument& doc, std::string etag = "") {
    return ports::NetResult::fromStatus(status, serialize(doc), std::move(etag));
}

ports::NetResult invalidRequest(const char* path, const char* message) {
    JsonDocument doc;
    doc["error"] = "invalid_request";
    JsonObject issue = doc["issues"].add<JsonObject>();
    issue["path"] = path;
    issue["message"] = message;
    return jsonResult(400, doc);
}

}  // namespace

FakeNetwork::FakeNetwork(ports::IClock& clock) : clock_(clock) {
    // The header is generated from the committed fixture at build time, so a parse failure here is a
    // build bug, not a runtime condition; an empty document would just make every lookup null.
    deserializeJson(state_, kFakeStateJson);
    baseNow_ = state_["now"] | int64_t{0};
}

int64_t FakeNetwork::nowMs() { return baseNow_ + static_cast<int64_t>(clock_.monotonicMs()); }

std::string FakeNetwork::etag() const { return "W/\"sim-" + std::to_string(generation_) + "\""; }

bool FakeNetwork::authorized(ports::NetResult& reject) const {
    if (token_ == kToken) return true;
    JsonDocument doc;
    doc["error"] = "unauthorized";
    reject = jsonResult(401, doc);
    return false;
}

ports::NetResult FakeNetwork::pairStart(const std::string& deviceId, const std::string& hwModel, const std::string& fw,
                                        const std::string& pollSecret) {
    if (deviceId.size() != 32) return invalidRequest("deviceId", "32 lowercase hex chars");
    if (hwModel.empty()) return invalidRequest("hwModel", "required");
    if (fw.empty()) return invalidRequest("fwVersion", "semver");
    if (pollSecret.size() < 32 || pollSecret.size() > 64) return invalidRequest("pollSecret", "32-64 lowercase hex chars");
    pairingDeviceId_ = deviceId;
    pollSecret_ = pollSecret;
    checks_ = 0;
    JsonDocument doc;
    doc["pairCode"] = kPairCode;
    doc["expiresAt"] = nowMs() + kPairTtlMs;
    doc["pollAfterSec"] = 1;
    return jsonResult(200, doc);
}

ports::NetResult FakeNetwork::pairCheck(const std::string& deviceId, const std::string& pollSecret) {
    JsonDocument doc;
    if (pairingDeviceId_.empty() || deviceId != pairingDeviceId_) {
        doc["status"] = "unknown";
    } else if (pollSecret != pollSecret_) {
        // Same answer as the server: the device id is public, the secret is what proves the poller
        // is the device that started the pairing. The counter does not advance for a stranger.
        doc["status"] = "pending";
    } else if (++checks_ <= kPendingChecks) {
        doc["status"] = "pending";
    } else {
        doc["status"] = "confirmed";
        doc["deviceToken"] = kToken;
        doc["houseId"] = state_["house"]["id"];
        doc["houseName"] = state_["house"]["name"];
        doc["deviceName"] = state_["device"]["name"];
    }
    return jsonResult(200, doc);
}

ports::NetResult FakeNetwork::getState(const std::string& ifNoneMatch) {
    ports::NetResult reject;
    if (!authorized(reject)) return reject;
    const std::string tag = etag();
    if (!ifNoneMatch.empty() && ifNoneMatch == tag) return ports::NetResult::fromStatus(304, "", tag);
    // `now` is outside the ETag on the server too: a device polling on its timer gets 304s until
    // something it displays changed, yet every full response carries fresh server time.
    state_["now"] = nowMs();
    return jsonResult(200, state_, tag);
}

ports::NetResult FakeNetwork::postFeedings(const std::string& jsonArray) {
    ports::NetResult reject;
    if (!authorized(reject)) return reject;
    JsonDocument body;
    if (deserializeJson(body, jsonArray) || !body.is<JsonArray>() || body.as<JsonArray>().size() == 0) {
        return invalidRequest("", "array of 1-100 feedings");
    }
    const int64_t now = nowMs();
    JsonArray cats = state_["cats"].as<JsonArray>();

    // A cat that is not in the house is reported before anything is written, as the server does.
    JsonDocument missing;
    JsonArray missingIds = missing["catIds"].to<JsonArray>();
    for (JsonObject item : body.as<JsonArray>()) {
        const char* catId = item["catId"] | "";
        bool found = false;
        for (JsonObject cat : cats) {
            if (std::strcmp(cat["id"] | "", catId) == 0) { found = true; break; }
        }
        if (!found) missingIds.add(catId);
    }
    if (missingIds.size() > 0) {
        missing["error"] = "cat_not_found";
        return jsonResult(404, missing);
    }

    JsonDocument resp;
    JsonArray accepted = resp["accepted"].to<JsonArray>();
    JsonArray clamped = resp["clamped"].to<JsonArray>();
    for (JsonObject item : body.as<JsonArray>()) {
        const char* id = item["id"] | "";
        const char* catId = item["catId"] | "";
        int64_t fedAt = item["fedAt"] | int64_t{0};
        if (fedAt > now + kFedAtMaxFutureMs || fedAt < kFedAtUnsetBeforeMs) {
            fedAt = now;
            clamped.add(id);
        }
        accepted.add(id);
        for (JsonObject cat : cats) {
            if (std::strcmp(cat["id"] | "", catId) != 0) continue;
            // The server keeps the latest feeding per cat: lastFedAt only moves forward, and the
            // "default for next time" follows whichever feeding is newest.
            const int64_t last = cat["lastFedAt"] | int64_t{0};
            if (fedAt >= last) {
                cat["lastFedAt"] = fedAt;
                cat["defaultAmountMg"] = item["amountMg"];
                cat["defaultEnteredUnit"] = item["enteredUnit"];
                cat["defaultEnteredValue"] = item["enteredValue"];
            }
            break;
        }
    }
    ++generation_;  // the cats changed, so the next getState must not be a 304
    resp["now"] = now;
    return jsonResult(201, resp);
}

ports::NetResult FakeNetwork::postLogs(const std::string& jsonArray) {
    ports::NetResult reject;
    if (!authorized(reject)) return reject;
    JsonDocument body;
    if (deserializeJson(body, jsonArray) || !body.is<JsonArray>()) return invalidRequest("", "array of log entries");
    return ports::NetResult::fromStatus(202, "");
}

ports::NetResult FakeNetwork::postHeartbeat(const std::string& jsonBody) {
    ports::NetResult reject;
    if (!authorized(reject)) return reject;
    JsonDocument body;
    if (deserializeJson(body, jsonBody) || !body.is<JsonObject>() || !body["fwVersion"].is<const char*>()) {
        return invalidRequest("fwVersion", "semver");
    }
    JsonDocument doc;
    doc["now"] = nowMs();
    return jsonResult(200, doc);
}

}  // namespace feedme2::adapters

#endif  // SIMULATOR
